const http = require('http');
const fs = require('fs');
const path = require('path');

const DEFAULT_PORT = 3000;
const DEFAULT_CATEGORY = 'general';

function round2(value) {
  return Math.round(value * 100) / 100;
}

function loadEntries(dataFile) {
  let raw;
  try {
    raw = fs.readFileSync(dataFile, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  try {
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) throw new Error('top-level value is not an array');
    return parsed;
  } catch (err) {
    throw new Error(`data file ${dataFile} is corrupted (${err.message}); refusing to start with empty data`);
  }
}

// 原子写：先写临时文件再 rename，避免半截文件
function saveEntries(dataFile, entries) {
  fs.mkdirSync(path.dirname(dataFile), { recursive: true });
  const tmpFile = `${dataFile}.tmp`;
  fs.writeFileSync(tmpFile, `${JSON.stringify(entries, null, 2)}\n`);
  fs.renameSync(tmpFile, dataFile);
}

// 应用工厂：测试注入 dataFile；write-then-commit —— 写盘成功后才更新内存
function createApp(options = {}) {
  const dataFile = options.dataFile || process.env.DATA_FILE || path.join('data', 'entries.json');
  let entries = loadEntries(dataFile);
  let nextId = entries.reduce((max, e) => Math.max(max, e.id || 0), 0) + 1;

  const server = http.createServer((req, res) => {
    const url = new URL(req.url, 'http://localhost');
    const send = (status, body) => {
      res.statusCode = status;
      res.setHeader('content-type', 'application/json');
      res.end(JSON.stringify(body));
    };

    if (req.method === 'POST' && url.pathname === '/entries') {
      let body = '';
      req.on('data', (chunk) => { body += chunk; });
      req.on('error', () => { res.destroy(); });
      req.on('end', () => {
        let parsed;
        try {
          parsed = JSON.parse(body || '{}');
        } catch {
          return send(400, { error: 'request body is not valid JSON' });
        }
        const { amount } = parsed;
        if (typeof amount !== 'number' || !Number.isFinite(amount) || amount <= 0) {
          return send(400, { error: 'amount must be a positive number' });
        }
        const note = parsed.note == null ? '' : String(parsed.note);
        const category = (typeof parsed.category === 'string' ? parsed.category : '').trim() || DEFAULT_CATEGORY;
        const entry = { id: nextId, amount: round2(amount), note, category, ts: Date.now() };
        const next = entries.concat([entry]);
        try {
          saveEntries(dataFile, next);
        } catch (err) {
          return send(500, { error: `failed to persist entry: ${err.message}` });
        }
        entries = next;
        nextId += 1;
        return send(201, entry);
      });
      return;
    }

    if (req.method === 'GET' && url.pathname === '/entries') {
      const category = url.searchParams.get('category');
      const list = category == null ? entries : entries.filter((e) => e.category === category);
      return send(200, list);
    }

    if (req.method === 'GET' && url.pathname === '/summary') {
      const byCategory = {};
      let total = 0;
      for (const e of entries) {
        total += e.amount;
        byCategory[e.category] = round2((byCategory[e.category] || 0) + e.amount);
      }
      return send(200, { total: round2(total), count: entries.length, byCategory });
    }

    const deleted = req.method === 'DELETE' && url.pathname.match(/^\/entries\/(\d+)$/);
    if (deleted) {
      const id = Number(deleted[1]);
      if (!entries.some((e) => e.id === id)) {
        return send(404, { error: `entry ${id} not found` });
      }
      const next = entries.filter((e) => e.id !== id);
      try {
        saveEntries(dataFile, next);
      } catch (err) {
        return send(500, { error: `failed to persist deletion: ${err.message}` });
      }
      entries = next;
      return send(200, { deleted: true });
    }

    return send(404, { error: 'not found' });
  });

  return server;
}

module.exports = { createApp };

if (require.main === module) {
  let app;
  try {
    app = createApp();
  } catch (err) {
    console.error(err.message);
    process.exit(1);
  }
  const port = Number(process.env.PORT) || DEFAULT_PORT;
  const dataFile = process.env.DATA_FILE || path.join('data', 'entries.json');
  app.listen(port, () => {
    console.log(`mini-ledger listening on http://localhost:${port} (data file: ${dataFile})`);
  });
}

