const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { createApp } = require('../src/server.js');

function tmpDataFile(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'mini-ledger-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  return path.join(dir, 'entries.json');
}

function startApp(t, dataFile) {
  const server = createApp({ dataFile });
  return new Promise((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      t.after(() => server.close());
      resolve(`http://127.0.0.1:${server.address().port}`);
    });
  });
}

async function call(base, method, route, rawBody) {
  const res = await fetch(`${base}${route}`, {
    method,
    headers: rawBody === undefined ? {} : { 'content-type': 'application/json' },
    body: rawBody,
  });
  const text = await res.text();
  let json = null;
  try { json = JSON.parse(text); } catch { /* keep null */ }
  return { status: res.status, headers: res.headers, text, json };
}

test('U1: minimal entry creation applies defaults', async (t) => {
  const base = await startApp(t, tmpDataFile(t));
  const res = await call(base, 'POST', '/entries', JSON.stringify({ amount: 12.5 }));
  assert.equal(res.status, 201);
  assert.equal(res.json.amount, 12.5);
  assert.equal(res.json.note, '');
  assert.equal(res.json.category, 'general');
  assert.ok(Number.isInteger(res.json.id));
  assert.ok(typeof res.json.ts === 'number');
});

test('U1: invalid JSON returns 400 and the process stays alive (AE1)', async (t) => {
  const base = await startApp(t, tmpDataFile(t));
  const bad = await call(base, 'POST', '/entries', 'not json');
  assert.equal(bad.status, 400);
  assert.ok(bad.json && typeof bad.json.error === 'string');
  const after = await call(base, 'GET', '/entries');
  assert.equal(after.status, 200);
  assert.deepEqual(after.json, []);
});

test('U1: invalid amounts are rejected (AE2)', async (t) => {
  const base = await startApp(t, tmpDataFile(t));
  for (const body of ['{}', '{"amount":"abc"}', '{"amount":0}', '{"amount":-3}']) {
    const res = await call(base, 'POST', '/entries', body);
    assert.equal(res.status, 400, `expected 400 for ${body}`);
    assert.ok(res.json.error);
  }
});

