  const base = await startApp(t, tmpDataFile(t));
  const res = await call(base, 'POST', '/entries', JSON.stringify({ amount: 12.5 }));
  assert.equal(res.status, 201);
  assert.equal(res.json.amount, 12.5);
  assert.equal(res.json.note, '');
  assert.equal(res.json.category, 'general');
  assert.ok(Number.isInteger(res.json.id));
  assert.ok(typeof res.json.ts === 'number');
});

test('U1: invalid JSON returns 400 and the process stays alive (AE1)', async (t) => {
  const base = await startApp(t, tmpDataFile(t));
  const bad = await call(base, 'POST', '/entries', 'not json');
  assert.equal(bad.status, 400);
  assert.ok(bad.json && typeof bad.json.error === 'string');
  const after = await call(base, 'GET', '/entries');
  assert.equal(after.status, 200);
  assert.deepEqual(after.json, []);
});

test('U1: invalid amounts are rejected (AE2)', async (t) => {
  const base = await startApp(t, tmpDataFile(t));
  for (const body of ['{}', '{"amount":"abc"}', '{"amount":0}', '{"amount":-3}']) {
    const res = await call(base, 'POST', '/entries', body);
    assert.equal(res.status, 400, `expected 400 for ${body}`);
    assert.ok(res.json.error);
  }
});

