test('U5: ids are never reused after deletion or restart', async (t) => {
  const dataFile = tmpDataFile(t);
  const base = await startApp(t, dataFile);
  const a = await call(base, 'POST', '/entries', JSON.stringify({ amount: 1 }));
  await call(base, 'POST', '/entries', JSON.stringify({ amount: 2 }));
  await call(base, 'DELETE', `/entries/${a.json.id}`);
  const c = await call(base, 'POST', '/entries', JSON.stringify({ amount: 3 }));
  assert.notEqual(c.json.id, a.json.id);
  const reloaded = await startApp(t, dataFile);
  const d = await call(reloaded, 'POST', '/entries', JSON.stringify({ amount: 4 }));
  assert.equal(d.json.id, c.json.id + 1);
});
